import { Drawer, Tabs } from 'antd'
import requestService from 'api/request'
import { formatNumber } from 'lib/helpers'
import React, { useEffect, useState } from 'react'
import { useTranslation } from 'react-i18next'

interface Props {
    setOpen: (val: boolean) => void,
    open: boolean,

}

const TeamInvite = ({ open, setOpen }: Props) => {
    const { t } = useTranslation()
    const [summary, setSummary] = useState<any>()
    const getSummaryTeam = async () => {
        try {
            const res = await requestService.get('/profile/summary-team')
            if (res && res?.data) {
                setSummary(res.data?.data)
            }

        } catch (error) {
            console.log('====================================');
            console.log(error);
            console.log('====================================');
        }
    }

    useEffect(() => {
        getSummaryTeam()
    }, [])
    return (
        <Drawer
            title={
                <div className='text-center'>
                    {t("TEAM")}
                </div>
            }
            placement={'right'}
            style={{
                background: "#fff"
            }}
            closable={true}
            closeIcon={
                <div>
                    <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="size-5 hover:text-[#000]">
                        <path strokeLinecap="round" strokeLinejoin="round" d="M15.75 19.5 8.25 12l7.5-7.5" />
                    </svg>


                </div>
            }
            onClose={() => setOpen(false)}
            width="100VW"
            open={open}

        >
            <div data-v-d324c76e="" className="team-page">

                <div data-v-d324c76e="" className="team-header">
                    <div data-v-d324c76e="" className="team-card">
                        <div data-v-d324c76e="" className="team-overview">
                            <div data-v-d324c76e="" className="total-count">
                                <span data-v-d324c76e="" className="label">
                                    Total team members
                                </span>
                                <span data-v-d324c76e="" className="value">
                                    {summary?.totalTeamMembers}
                                </span>
                            </div>
                            <div data-v-d324c76e="" className="level-counts">
                                <div data-v-d324c76e="" className="level-item">
                                    <span data-v-d324c76e="" className="value">
                                        {summary?.levelA?.length}
                                    </span>
                                    <span data-v-d324c76e="" className="label">
                                        Level A
                                    </span>
                                </div>
                                <div data-v-d324c76e="" className="level-item">
                                    <span data-v-d324c76e="" className="value">
                                        {summary?.levelB?.length}
                                    </span>
                                    <span data-v-d324c76e="" className="label">
                                        Level B
                                    </span>
                                </div>
                                <div data-v-d324c76e="" className="level-item">
                                    <span data-v-d324c76e="" className="value">
                                        {summary?.levelC?.length}
                                    </span>
                                    <span data-v-d324c76e="" className="label">
                                        Level C
                                    </span>
                                </div>
                            </div>
                        </div>
                        <div data-v-d324c76e="" className="team-earnings">
                            <div data-v-d324c76e="" className="earning-item">
                                <span data-v-d324c76e="" className="value">
                                    {formatNumber(summary?.totalEarningValue)}
                                </span>
                                <span data-v-d324c76e="" className="label">
                                    Total earnings
                                </span>
                            </div>
                            <div data-v-d324c76e="" className="earning-item">
                                <span data-v-d324c76e="" className="value">
                                    {formatNumber(summary?.totalEarningValueToday)}
                                </span>
                                <span data-v-d324c76e="" className="label">
                                    Today's earnings
                                </span>
                            </div>
                        </div>
                    </div>
                </div>
                <div data-v-d324c76e="" className="team-content">
                    <Tabs
                        defaultActiveKey="a"

                        className='tab-team'
                        size='large'
                        centered
                        items={[
                            {
                                key: "a",
                                label: "Level A",
                                children: <div>
                                    <div data-v-d324c76e="" className="member-list">
                                        <div data-v-d324c76e className='member-item'>
                                            <div data-v-d324c76e className='member-info'>
                                                <div data-v-d324c76e className='info-content'>
                                                    <div data-v-d324c76e className='name-row'>
                                                        <div data-v-d324c76e >
                                                            <div className='name'>
                                                                div
                                                            </div>
                                                        </div>
                                                    </div>
                                                </div>
                                            </div>
                                        </div>
                                        <div data-v-d324c76e="" role="feed" className="van-list" aria-busy="false">
                                            {/**/}
                                            <div className="van-list__finished-text">No more</div>
                                            {/**/}
                                            <div className="van-list__placeholder" />
                                        </div>
                                    </div>

                                </div>,
                            },
                            {
                                key: "b",
                                label: "Level B",
                                children: <div>
                                    <div data-v-d324c76e="" className="member-list">
                                        <div data-v-d324c76e="" role="feed" className="van-list" aria-busy="false">
                                            {/**/}
                                            <div className="van-list__finished-text">No more</div>
                                            {/**/}
                                            <div className="van-list__placeholder" />
                                        </div>
                                    </div>

                                </div>,
                            },
                            {
                                key: "c",
                                label: "Level C",
                                children: <div>
                                    <div data-v-d324c76e="" className="member-list">
                                        <div data-v-d324c76e="" role="feed" className="van-list" aria-busy="false">
                                            {/**/}
                                            <div className="van-list__finished-text">No more</div>
                                            {/**/}
                                            <div className="van-list__placeholder" />
                                        </div>
                                    </div>

                                </div>,
                            },
                        ]}

                    />
                </div>
            </div>

        </Drawer>
    )
}

export default TeamInvite
